import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiStation","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/index.md","filePath":"modules/station/index.md","lastUpdated":0}`),a={name:`modules/station/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakistation" tabindex="-1">EmakiStation <a class="header-anchor" href="#emakistation" aria-label="Permalink to “EmakiStation”">​</a></h1><p>用大白话认识 EmakiStation: 它是做什么的, 你会用到哪些文件, 以及第一次打开工作站要敲哪几条命令</p><p>EmakiStation 是 Emaki 系列的通用合成工作站. 你按配方投入材料, 材料排进队列, 到点就能领取产物, 整条流程都做成了一个可以自由配置的界面工作站. 它还附带一套独立的分解站</p><p>合成侧一共有三页界面 (配方目录 → 材料预览 → 合成队列). 队列按顺序一个接一个推进, 同一时刻只有排在最前面的条目在做. 材料从「背包和仓库」合并成的一个池子里扣除, 装了 EmakiStorage 后仓库也会参与供料; 产物按配置送到仓库或背包, 两边都放不下时会进入待领取状态, 既不会掉落, 也不会销毁</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.0.0</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-station-api:2.0.0</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.station.EmakiStationPlugin</code></td></tr><tr><td>主命令</td><td><code>/emakistation</code></td></tr><tr><td>别名</td><td><code>/estation</code>, <code>/est</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiStorage, PlaceholderAPI</td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;26.1&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakistation.use</code> (默认 true), <code>emakistation.purchase</code> (默认 true), <code>emakistation.dismantle</code> (默认 true), <code>emakistation.reload</code> (op), <code>emakistation.debug</code> (op), <code>emakistation.admin</code> (op)</td></tr></tbody></table><p>这里有一组容易混淆的版本号, 先分清: 模块本体、默认 <code>config.yml</code> 与 API 构件的版本值都是 <code>2.0.0</code>. 源码里的 <code>AppConfig.CURRENT_VERSION = &quot;1.0.2&quot;</code> 是配置迁移用的结构常量, 跟前两者用途不同, 不要混用</p><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/emakistation</code> 的 9 个功能子命令 (另有 <code>help</code>), 6 个权限节点与两个访问权限前缀</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的 <code>queue</code>, <code>limits</code>, <code>storage</code>, <code>persistence</code>, <code>gui</code> 五段, 含全部键与默认值</td></tr><tr><td><a href="./stations.html">工作站定义</a></td><td><code>stations/&lt;id&gt;.yml</code> 的布局, 权限, 队列参数, 材料通道, 产物去向与条件检查</td></tr><tr><td><a href="./recipes.html">配方定义</a></td><td><code>recipes/&lt;配方&gt;.yml</code> 的归属, 材料, 产物, 耗时, 货币成本, 动作段与两种条件检查</td></tr><tr><td><a href="./queue.html">合成队列</a></td><td>队列长度的三个来源, 逐个推进, 取消退还与待领取状态</td></tr><tr><td><a href="./queue-costs.html">付费队列位</a></td><td><code>queue_costs.yml</code> 的档位, 逐格计价, 三道开关与 <code>unlocks.yml</code> 已购存档</td></tr><tr><td><a href="./dismantle.html">物品分解</a></td><td>独立分解站与分解配方的 <code>item_sources</code>, <code>rolls</code>, <code>pool</code> 权重抽取</td></tr><tr><td><a href="./gui.html">界面模板</a></td><td>四份 GUI 模板的槽位类型, 占位符全集与「必须显式写 <code>type:</code>」的约束</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td><code>emaki-station-api</code> 的门面, 查询与操作接口及线程约束</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>StationCraftSubmitEvent</code>, <code>StationCraftCancelEvent</code>, <code>StationCraftCompletedEvent</code></td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>无序集合匹配</strong>: 配方只数材料的种类和总数, 不看放在哪一格, 也没有摆放形状的概念. <code>item_sources</code> 是「任意其一」集合, 数量按集合内总数计算 -- 需要 64 个时, 30 个 coal 加 34 个 charcoal 也算满足</li><li><strong>背包与仓库合并供料</strong>: 两个通道都开启时, 材料来自合并后的一个池子, 优先扣背包. 你看不到通道切换按钮, 界面里显示的「拥有」就是两边合计</li><li><strong>串行单线队列</strong>: 你在一个工作站只有一条队列, 同一时刻只有排在最前面的条目在推进. <code>waiting</code> 与 <code>running</code> 占用队列长度, <code>pending_claim</code> 不占用</li><li><strong>队列长度三来源</strong>: 队列能排多长由三样东西决定: 基础长度, <code>emakistation.queue.&lt;n&gt;</code> 权限档, 付费购买. 权限档<strong>取代</strong>基础长度, 付费额度<strong>叠加</strong>在其上, 最终统一被 <code>max_length</code> 截断</li><li><strong>产物永不丢失</strong>: 所有配置的去处都放不下时, 条目转为待领取, 等你用 <code>/emakistation claim</code> 或界面按钮领取</li><li><strong>分解站完全独立</strong>: 分解站与合成站 ID 互不关联, 各自在 <code>stations_dismantle/</code> 与 <code>recipes_dismantle/</code> 目录加载, 不是工作站的第四页</li></ul><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to “文件结构”">​</a></h2><p>服务器跑起来后, EmakiStation 主要用到下面这些文件:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStation/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ queue_costs.yml</span></span>
<span class="line"><span>├─ stations/</span></span>
<span class="line"><span>│  ├─ blacksmith.yml</span></span>
<span class="line"><span>│  └─ example_altar.yml</span></span>
<span class="line"><span>├─ recipes/</span></span>
<span class="line"><span>│  ├─ example_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_component_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_weapon_recipe.yml</span></span>
<span class="line"><span>│  └─ example_queue_recipe.yml</span></span>
<span class="line"><span>├─ stations_dismantle/</span></span>
<span class="line"><span>│  ├─ example_dismantle_station.yml</span></span>
<span class="line"><span>│  └─ example_weapon_dismantle_station.yml</span></span>
<span class="line"><span>├─ recipes_dismantle/</span></span>
<span class="line"><span>│  ├─ example_dismantle_recipe.yml</span></span>
<span class="line"><span>│  ├─ example_component_dismantle_recipe.yml</span></span>
<span class="line"><span>│  └─ example_weapon_dismantle_recipe.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ station_catalog.yml</span></span>
<span class="line"><span>│  ├─ station_preview.yml</span></span>
<span class="line"><span>│  ├─ station_queue.yml</span></span>
<span class="line"><span>│  ├─ station_dismantle.yml</span></span>
<span class="line"><span>│  ├─ editor_browser_gui.yml</span></span>
<span class="line"><span>│  └─ editor_page_gui.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;UUID&gt;/</span></span>
<span class="line"><span>│     └─ unlocks.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置, 管队列默认值, 容量上限, 仓库通道, 持久化与界面刷新限制</td></tr><tr><td><code>queue_costs.yml</code></td><td>付费队列位的档位. 属于业务数据文件, 只在缺失时释放一次, 版本升级不会覆盖管理员改过的内容</td></tr><tr><td><code>stations/&lt;id&gt;.yml</code></td><td>合成工作站定义, 文件名与 <code>id</code> 一致</td></tr><tr><td><code>recipes/&lt;配方&gt;.yml</code></td><td>合成配方定义, 一个文件一条配方, 归属由配方侧的 <code>station_ids</code> 声明</td></tr><tr><td><code>stations_dismantle/&lt;id&gt;.yml</code></td><td>分解站定义, 与合成站互不关联</td></tr><tr><td><code>recipes_dismantle/&lt;配方&gt;.yml</code></td><td>分解配方定义, 含输入物品与产物概率池</td></tr><tr><td><code>gui/*.yml</code></td><td>四份界面模板: 配方目录, 材料预览, 合成队列, 分解界面</td></tr><tr><td><code>data/&lt;玩家 UUID&gt;/unlocks.yml</code></td><td>每个玩家已购队列位的存档, 由插件自动维护, 额度为空时不生成该文件. 见<a href="./queue-costs.html">付费队列位</a></td></tr><tr><td><code>lang/*.yml</code></td><td>命令, 界面, 启动预检与控制台里的文案</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><ol><li>先把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiStation-*.jar</code> 放入服务器 <code>plugins/</code></li><li>不要把 <code>emaki-station-api-*.jar</code> 放进 <code>plugins/</code>; API Jar 只给开发者当编译依赖用</li><li>首次启动后, 打开 <code>plugins/EmakiStation/config.yml</code> 和示例工作站 <code>stations/blacksmith.yml</code> 看一眼</li><li>打开示例工作站:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation open blacksmith</span></span></code></pre></div><ol start="5"><li>想看自己的队列, 或者领取产物, 用这两条:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation queue</span></span>
<span class="line"><span>/emakistation claim</span></span></code></pre></div><ol start="6"><li>改完配置后, 重载让它生效:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation reload</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>注意, 工作站的 <code>channels.backpack</code> 与 <code>channels.storage</code> 不能同时为 false, 否则这个工作站会被拒绝加载. 这样的配置能打开, 却永远用不了, 插件宁可在启动时就报错</li><li><code>channels.default</code> 是保留键, 现在已经不生效了. 通道合并之后, 「停在哪个通道」这件事就不存在了; 插件仍会读取这个值, 但没有任何地方真正用到它, 留着只是为了让旧配置不报未知键</li><li>想用仓库通道, 光有 <code>storage.enabled: true</code> 还不够, EmakiStorage 还得提供 <code>emakistorage:atomic_batch</code> 能力 (一批操作要么全做, 要么全不做的批量接口). 缺这个能力时插件<strong>不会</strong>改成逐个取出, 因为那会让材料在你的背包里闪现一次</li><li>注意 <code>progress_mode: offline</code> 只表示「计时继续」, 不表示「离线发货」. 离线期间到点的条目只是到了期, 真正结算发生在玩家下次上线时</li><li>三份布局文件 (<code>layout</code>, <code>preview_layout</code>, <code>queue_layout</code>) 一个都不能少, 缺任何一份, 启动预检都会报 <code>missing_layout</code></li><li><strong>确定性最大流材料分配</strong>: 你点提交时, 插件把背包里的一堆堆物品与仓库里的库存一起放进一张分配图, 在全部需求之间寻找一套能同时满足的完整分配, 不再依赖配方声明顺序. 约束更窄的 matcher 材料会优先参与建图, 但最终仍然以整体上能不能分配为准; 如果分配失败, 说明当前候选材料确实无法同时满足全部需求</li><li><strong>尚未接通的功能</strong>: EmakiStation 目前不注册任何动作段 id, 也不注册 PlaceholderAPI 扩展. 配方里的 <code>actions.pre</code> / <code>success</code> / <code>failure</code>, <code>result.actions</code>, 以及工作站与分解站级别的 <code>condition</code>, 都会被解析并保存, 但目前没有执行入口; <code>limits.batch_multiplier_max</code> 同样只被解析, 不参与校验. 想看细节, 见<a href="./recipes.html">配方定义</a>, <a href="./stations.html">工作站定义</a>, <a href="./dismantle.html">物品分解</a>与<a href="./configuration.html">配置详解</a></li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};